<?php use VazinCMS\Security; ?>
<section class="public-main"><header class="public-card"><span class="eyebrow">Telegram</span><h1>آرشیو کانال</h1><p>مطالب با تاریخ اصلی انتشار در Telegram نمایش داده می‌شوند.</p></header>
<?php foreach($posts as$post):?><article class="public-card"><time datetime="<?=Security::e((string)($post['published_at']?:$post['created_at']))?>"><?=Security::e(substr((string)($post['published_at']?:$post['created_at']),0,10))?></time><h2><a href="/<?=Security::e($post['locale'])?>/page/<?=Security::e($post['slug'])?>"><?=Security::e($post['title'])?></a></h2><p><?=Security::e(mb_substr(trim(preg_replace('/\s+/u',' ',strip_tags((string)$post['body']))??''),0,280))?></p><a href="/<?=Security::e($post['locale'])?>/page/<?=Security::e($post['slug'])?>">ادامه مطلب</a></article><?php endforeach;?><?php if(!$posts):?><div class="public-card"><p>هنوز مطلبی از کانال همگام نشده است.</p></div><?php endif;?>
<?php if($pages>1):?><nav class="public-card" aria-label="صفحه‌بندی"><?php if($page>1):?><a href="?page=<?=$page-1?>">صفحه قبل</a><?php endif;?><span>صفحه <?=$page?> از <?=$pages?></span><?php if($page<$pages):?><a href="?page=<?=$page+1?>">صفحه بعد</a><?php endif;?></nav><?php endif;?></section>
